package com.sakib.portebo.ui.adapter;
import android.content.Context;import com.sakib.portebo.util.IconCache;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.view.animation.PathInterpolator;import android.widget.FrameLayout;import android.widget.ImageView;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.EditText;import android.widget.Toast;import android.text.InputType;import androidx.appcompat.app.AlertDialog;import com.google.android.material.dialog.MaterialAlertDialogBuilder;import com.google.android.material.textfield.TextInputLayout;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButton;import com.sakib.portebo.R;import com.sakib.portebo.data.AppTierManager;import com.sakib.portebo.model.AppItem;import com.sakib.portebo.security.ParentControlManager;import com.sakib.portebo.util.AnimUtils;import java.util.ArrayList;import java.util.List;import java.util.Locale;
public class AppTierAdapter extends RecyclerView.Adapter<AppTierAdapter.Holder>{public interface TierChangeListener{void onChanged(AppItem.Tier oldTier,AppItem.Tier newTier);}private final Context c;private final List<AppItem> all=new ArrayList<>();private List<AppItem> shown=new ArrayList<>();private final TierChangeListener changed;private String query="";private AppItem.Tier tierFilter;private boolean editingEnabled=true;
 public AppTierAdapter(Context c,List<AppItem> a,TierChangeListener changed){this.c=c.getApplicationContext();this.changed=changed;updateData(a);}public AppTierAdapter(Context c,List<AppItem>a){this(c,a,(TierChangeListener)null);}
 public void updateData(List<AppItem>a){all.clear();all.addAll(a);applyFilters();}public void filter(String q){query=q==null?"":q;applyFilters();}public void setTierFilter(AppItem.Tier tier){tierFilter=tier;applyFilters();}public void setEditingEnabled(boolean enabled){editingEnabled=enabled;notifyDataSetChanged();}private boolean canEdit(){return ParentControlManager.requireEditAccess(c)&&editingEnabled;}private void applyFilters(){String x=query.toLowerCase(Locale.ROOT);shown.clear();for(AppItem a:all){boolean matchesText=x.isEmpty()||a.getName().toLowerCase(Locale.ROOT).contains(x)||a.getPackageName().toLowerCase(Locale.ROOT).contains(x);boolean matchesTier=tierFilter==null||a.getTier()==tierFilter;if(matchesText&&matchesTier)shown.add(a);}notifyDataSetChanged();}
 @NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_app_tier,p,false));}
 public void onBindViewHolder(@NonNull Holder h,int pos){AppItem a=shown.get(pos);h.bound=a;h.name.setText(a.getName());h.role.setText(a.getRole());IconCache.load(c,a.getPackageName(),h.icon);h.protectedBadge.setVisibility(a.isProtected()?View.VISIBLE:View.GONE);h.pill.setVisibility(a.isProtected()?View.GONE:View.VISIBLE);h.quota.setVisibility(!a.isProtected()&&a.getTier()==AppItem.Tier.GREYLIST?View.VISIBLE:View.GONE);if(a.isProtected())return;boolean edit=editingEnabled&&ParentControlManager.canEdit(c);h.white.setEnabled(edit);h.grey.setEnabled(edit);h.black.setEnabled(edit);h.quotaValue.setEnabled(edit);h.dec.setEnabled(edit);h.inc.setEnabled(edit);float editAlpha=edit?1f:.45f;h.white.setAlpha(editAlpha);h.grey.setAlpha(editAlpha);h.black.setAlpha(editAlpha);h.quotaValue.setAlpha(editAlpha);h.dec.setAlpha(editAlpha);h.inc.setAlpha(editAlpha);
 h.white.setOnClickListener(v->setTier(h,a,AppItem.Tier.WHITELIST,0));h.grey.setOnClickListener(v->setTier(h,a,AppItem.Tier.GREYLIST,1));h.black.setOnClickListener(v->setTier(h,a,AppItem.Tier.BLACKLIST,2));int ix=index(a.getTier());h.pill.post(()->{if(h.bound!=a)return;int w=(h.pill.getWidth()-h.pill.getPaddingLeft()-h.pill.getPaddingRight())/3;ViewGroup.LayoutParams lp=h.indicator.getLayoutParams();if(w>0&&lp.width!=w){lp.width=w;h.indicator.setLayoutParams(lp);}h.indicator.setTranslationX(ix*w);});color(h,a.getTier());h.quotaValue.setText((a.getQuotaSeconds()/60)+" মিনিট");h.quotaValue.setOnClickListener(v->{if(canEdit())editQuota(a,h);});h.dec.setOnClickListener(v->{if(!canEdit())return;int n=Math.max(60,a.getQuotaSeconds()-60);a.setQuotaSeconds(n);AppTierManager.saveTiersDebounced(c);notifyItemChanged(h.getBindingAdapterPosition());});h.inc.setOnClickListener(v->{if(!canEdit())return;int n=Math.min(10800,a.getQuotaSeconds()+60);a.setQuotaSeconds(n);AppTierManager.saveTiersDebounced(c);notifyItemChanged(h.getBindingAdapterPosition());});}
 private void editQuota(AppItem app,Holder holder){
  if(!canEdit())return;
  android.content.Context context=holder.itemView.getContext();
  View form=LayoutInflater.from(context).inflate(R.layout.dialog_quota_editor,null,false);
  TextInputLayout field=form.findViewById(R.id.tilQuotaMinutes);EditText input=form.findViewById(R.id.etQuotaMinutes);
  input.setText(String.valueOf(Math.max(1,app.getQuotaSeconds()/60)));input.setSelection(input.getText().length());
  AlertDialog dialog=new MaterialAlertDialogBuilder(context).setTitle("টাইমার কোটা").setView(form).setNegativeButton("বাতিল",null).setPositiveButton("সেভ",null).create();
  dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!canEdit())return;int minutes;try{minutes=Integer.parseInt(input.getText().toString().trim());}catch(Exception e){minutes=0;}if(minutes<1||minutes>180){field.setError("১–১৮০ মিনিটের মধ্যে দাও");input.requestFocus();return;}field.setError(null);int seconds=minutes*60,used=app.getUsedSeconds();app.setQuotaSeconds(seconds);if(used>seconds){app.setUsedSeconds(seconds);com.sakib.portebo.data.PrefsManager.saveGreylistUsedSeconds(app.getPackageName(),seconds);}com.sakib.portebo.data.AppTierManager.saveTiersDebounced(c);com.sakib.portebo.service.AppMonitorService.onQuotaChanged(c,app.getPackageName());int position=holder.getBindingAdapterPosition();if(position!=RecyclerView.NO_POSITION)notifyItemChanged(position);dialog.dismiss();}));
  input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){field.setError(null);}public void afterTextChanged(android.text.Editable e){}});
  dialog.show();
 }
 private int index(AppItem.Tier t){return t==AppItem.Tier.WHITELIST?0:t==AppItem.Tier.GREYLIST?1:2;}private void color(Holder h,AppItem.Tier t){int white=0xffffffff,normal=0xff64748b;h.white.setTextColor(t==AppItem.Tier.WHITELIST?white:normal);h.grey.setTextColor(t==AppItem.Tier.GREYLIST?white:normal);h.black.setTextColor(t==AppItem.Tier.BLACKLIST?white:normal);}
 private void setTier(Holder h,AppItem a,AppItem.Tier t,int ix){if(!canEdit()||a.getTier()==t)return;AppItem.Tier old=a.getTier();AppTierManager.setTier(c,a.getPackageName(),t);int w=(h.pill.getWidth()-h.pill.getPaddingLeft()-h.pill.getPaddingRight())/3;float x=ix*w;if(AnimUtils.areAnimationsEnabled(c))h.indicator.animate().translationX(x).setDuration(240).setInterpolator(new PathInterpolator(.25f,.1f,.25f,1f)).start();else h.indicator.setTranslationX(x);color(h,t);h.quota.setVisibility(t==AppItem.Tier.GREYLIST?View.VISIBLE:View.GONE);h.quotaValue.setText((a.getQuotaSeconds()/60)+" মিনিট");if(changed!=null)changed.onChanged(old,t);}
 public int getItemCount(){return shown.size();}static class Holder extends RecyclerView.ViewHolder{AppItem bound;ImageView icon;TextView name,role,protectedBadge,white,grey,black,quotaValue;FrameLayout pill;View indicator;LinearLayout quota;MaterialButton dec,inc;Holder(View v){super(v);icon=v.findViewById(R.id.ivAppIcon);name=v.findViewById(R.id.tvAppName);role=v.findViewById(R.id.tvAppRole);protectedBadge=v.findViewById(R.id.tvProtectedBadge);pill=v.findViewById(R.id.pillToggleContainer);indicator=v.findViewById(R.id.pillIndicatorView);white=v.findViewById(R.id.btnTierWhitelist);grey=v.findViewById(R.id.btnTierGreylist);black=v.findViewById(R.id.btnTierBlacklist);quota=v.findViewById(R.id.layoutQuotaConfig);quotaValue=v.findViewById(R.id.tvQuotaValue);dec=v.findViewById(R.id.btnQuotaDecrease);inc=v.findViewById(R.id.btnQuotaIncrease);}}
}
